process.stdin.resume()
process.stdin.setEncoding('utf-8')

var arr = ''
process.stdin.on('data', (i) => {
  arr += i
})


process.stdin.on('end', () => {
  arr = arr.split('\n')
  const ax = arr.shift().split(' ')
  const v = parseInt(ax[0])
  const e = parseInt(ax[1])

  if(e == 0) {
    console.log(0)
    return
  }
  if(v <= 6) {
    console.log(e)
  }

  else {
    let m = new Map()

    for(let i = 1; i <= v; i ++) {
      m.set(i, [])
    }

    for(let i = 0; i < e; i ++) {
      const edge = arr.shift().split(' ')
      const a = parseInt(edge[0])
      const b = parseInt(edge[1])
      m.get(a).push(b)
      m.get(b).push(a)
    }

    var f = false
    var noOfVertices = 20
    for(let j = 1; j <= 7; j ++) {
      var a7 = m.get(j)
      for(let i = 1; i <= 7; i ++) {
        if(i == j) continue
        var other = m.get(i)
        var x = a7.filter(el => other.indexOf(el) != -1)
        if(x.length == 0) {
          f = true
          break
        }
        else if(x.length < noOfVertices) {
          noOfVertices = x.length
        }
      }
    }
    if(f) {
      console.log(e)
    }

    else {
      console.log(e - noOfVertices)
    }
  }
})
